      const auto result_digest = scratchbird::core::hash::ComputeSha256Digest(
          parameter_bind_result_bytes);
      const char* trace_path =
          std::getenv("SCRATCHBIRD_SBLR_DISPATCH_PHASE_TRACE_FILE");
